    caster:PerformAttack(
        target,
        true,
        true,
        true,
        false,
        false,
        false,
        false
    )
    local dealt = ApplyDamage({
        victim = target,
        attacker = caster,
        ability = self,
        damage = totalDmg,
        damage_type = 1
    })
